refentry.refsect1:
&reftitle.description;

 public intYaf_Config_Ini::count


Retorna o número de entradas de configuração de nível superior.

  &reftitle.examples;

   Exemplo de Yaf_Config_Ini::count


<?php
/**
 * Suponha que /etc/myapp/application.ini contenha:
 * [common]
 * application.name = "MyApp"
 * database.host    = "localhost"
 * database.port    = 3306
 */
$config = new Yaf_Config_Ini('/etc/myapp/application.ini', 'common');

// Apenas as entradas de nível superior ("application" e "database") são contadas
var_dump(count($config));
var_dump($config->count());
?>


   &example.outputs.similar;


int(2)
int(2)
